/// Get embedded weights for a specific layer
pub fn get_layer_weights(
    layer_idx: usize,
) -> Option<(&'static [f32], &'static [f32], usize, usize)> {
    match layer_idx {
        0 => Some((
            LAYER_0_WEIGHTS,
            LAYER_0_BIASES,
            LAYER_0_INPUT_SIZE,
            LAYER_0_OUTPUT_SIZE,
        )),
        1 => Some((
            LAYER_1_WEIGHTS,
            LAYER_1_BIASES,
            LAYER_1_INPUT_SIZE,
            LAYER_1_OUTPUT_SIZE,
        )),
        2 => Some((
            LAYER_2_WEIGHTS,
            LAYER_2_BIASES,
            LAYER_2_INPUT_SIZE,
            LAYER_2_OUTPUT_SIZE,
        )),
        3 => Some((
            LAYER_3_WEIGHTS,
            LAYER_3_BIASES,
            LAYER_3_INPUT_SIZE,
            LAYER_3_OUTPUT_SIZE,
        )),
        4 => Some((
            LAYER_4_WEIGHTS,
            LAYER_4_BIASES,
            LAYER_4_INPUT_SIZE,
            LAYER_4_OUTPUT_SIZE,
        )),
        _ => None,
    }
}

/// Load all embedded weights into layer format
pub fn load_embedded_weights() -> Vec<(Vec<Vec<f32>>, Vec<f32>)> {
    let mut layers = Vec::new();

    for layer_idx in 0..NUM_LAYERS {
        if let Some((weights, biases, input_size, output_size)) = get_layer_weights(layer_idx) {
            // Reshape flattened weights to 2D
            let mut weight_matrix = Vec::with_capacity(output_size);
            for i in 0..output_size {
                let start = i * input_size;
                let end = start + input_size;
                weight_matrix.push(weights[start..end].to_vec());
            }
            layers.push((weight_matrix, biases.to_vec()));
        }
    }

    layers
}

/// Decision threshold (train/results/EXPERIMENT_REPORT.md, threshold analysis)
pub const DEFAULT_THRESHOLD: f32 = 0.7;

/// Input feature size
pub const INPUT_SIZE: usize = 64;
